VISUAL_STUDIES.push({id:'two-song-mountain-worlds',assets:['china-batch-10-guoxi-early-spring','china-batch-10-fankuan-mountains-travelers'],title:b('Two ways into a Song landscape','进入宋代山水的两种方式'),question:b('Follow the paths, then find the people. How does each painter arrange the distance between a traveller and the mountain?','先循路径，再找行人：两位画家如何安排人和山之间的距离？'),observations:[
 b('Guo Xi’s Early Spring is dated 1072. Rock forms overlap and disappear into mist, shifting the view between near and distant places. The imperial poem at upper right was added by Qianlong in 1759, centuries after the painting.','郭熙《早春图》署1072年。山石重叠、隐入烟岚，视点在远近之间转换。右上御题诗是乾隆1759年所加，比画作晚数百年。'),
 b('Fan Kuan makes the travellers tiny beneath a huge central rock face. The painting is undated within the Northern Song; Dong Qichang’s later title sits above it. Compare its abrupt scale change with Guo Xi’s many connected views.','范宽把行旅画得极小，置于中央巨峰之下。本画属于北宋而未纪年，上方有董其昌后加题签；可把这强烈的尺度反差同郭熙相连的多重视点对读。')]});
export function availableVisualStudies(rows){const ids=new Set(rows.map(r=>r.id));return VISUAL_STUDIES.filter(s=>s.assets.length===2&&new Set(s.assets).size===2&&s.assets.every(id=>ids.has(id)));}
export function matchingVisualStudy(ids){if(ids.length!==2||new Set(ids).size!==2)return null;return VISUAL_STUDIES.find(s=>s.assets.every(id=>ids.includes(id)))||null;}
